typedef struct { int x, y; } Point;
typedef struct { Point tl, br; } Rect;
struct Student { char name[16]; int score; Rect box; };

Rect make_rect(int x1, int y1, int x2, int y2) {
    Rect r = {{x1, y1}, {x2, y2}};
    return r;
}

int area(Rect r) { return (r.br.x - r.tl.x) * (r.br.y - r.tl.y); }

void grow(Rect *r, int d) {
    r->tl.x -= d;
    r->tl.y -= d;
    r->br.x += d;
    (*r).br.y += d;
}

int cmp_score(const void *a, const void *b) {
    const struct Student *x = a, *y = b;
    return y->score - x->score;
}

int main(void) {
    struct Student cls[4];
    const char *names[] = {"Ann", "Bo", "Cyrus", "Dee"};
    int scores[] = {81, 95, 70, 88};
    for (int i = 0; i < 4; i++) {
        strcpy(cls[i].name, names[i]);
        cls[i].score = scores[i];
        cls[i].box = make_rect(0, 0, i + 1, i + 2);
    }
    qsort(cls, 4, sizeof cls[0], cmp_score);
    for (int i = 0; i < 4; i++)
        printf("%-8s|%5d|%3d\n", cls[i].name, cls[i].score, area(cls[i].box));
    Rect r = cls[0].box;
    grow(&r, 2);
    printf("%d %d (%d,%d)\n", area(r), area(cls[0].box), r.tl.x, r.br.y);
    struct Student *best = &cls[0];
    best->box.br.x *= 10;
    printf("%d\n", cls[0].box.br.x);
    return 0;
}

#include <stdio.h>

#define ROWS 3
#define COLS 4

void fill(int m[ROWS][COLS]) {
    for (int i = 0; i < ROWS; i++)
        for (int j = 0; j < COLS; j++)
            m[i][j] = i * COLS + j + 1;
}

void show(int r, int c, int m[r][c]) {
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++)
            printf("%3d", m[i][j]);
        putchar('\n');
    }
}

int row_sum(int (*row)[COLS], int n) {
    int s = 0;
    for (int k = 0; k < n; k++) s += (*row)[k];
    return s;
}

void transpose(int src[ROWS][COLS], int dst[COLS][ROWS]) {
    for (int i = 0; i < ROWS; i++)
        for (int j = 0; j < COLS; j++)
            dst[j][i] = src[i][j];
}

int main(void) {
    int m[ROWS][COLS], t[COLS][ROWS];
    fill(m);
    show(ROWS, COLS, m);
    transpose(m, t);
    show(COLS, ROWS, t);
    int (*row)[COLS] = m;
    for (int i = 0; i < ROWS; i++, row++)
        printf("row %d sum %d\n", i, row_sum(row, COLS));
    int *flat = &m[0][0];
    printf("%d %d\n", flat[5], *(*(m + 2) + 3));
    int tr = 0;
    for (int i = 0; i < ROWS; i++) tr += m[i][i];
    printf("trace=%d\n", tr);
    return 0;
}

