int push(int **arr, size_t *len, size_t *cap, int v) {
    if (*len == *cap) {
        size_t nc = *cap ? *cap * 2 : 1;
        int *t = (int *)realloc(*arr, nc * sizeof(int));
        if (t == NULL) return 0;
        *arr = t;
        *cap = nc;
    }
    (*arr)[(*len)++] = v;
    return 1;
}

