#include <stdio.h>

enum Flag { F_READ = 1, F_WRITE = 2, F_EXEC = 4, F_ALL = F_READ | F_WRITE | F_EXEC };

const char *flag_name(enum Flag f) {
    switch (f) {
    case F_READ: return "read";
    case F_WRITE: return "write";
    case F_EXEC: return "exec";
    default: return "?";
    }
}

int popcount(unsigned x) {
    int c = 0;
    while (x) { x &= x - 1; c++; }
    return c;
}

int main(void) {
