typedef int (*binop)(int, int);

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }
int mul(int a, int b) { return a * b; }

struct Op { const char *name; binop f; };

binop pick(char c) {
    switch (c) {
    case '+': return add;
    case '-': return sub;
    default: return mul;
    }
}

int next_id(void) {
    static int id = 100;
    return id++;
}

int fold(binop f, const int *v, int n, int init) {
    for (int i = 0; i < n; i++) init = f(init, v[i]);
    return init;
}

int cmp_desc(const void *a, const void *b) { return *(const int *)b - *(const int *)a; }

int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

int main(void) {
    struct Op ops[] = {{"add", add}, {"sub", sub}, {"mul", mul}};
    for (int i = 0; i < 3; i++)
        printf("%s(12,5)=%d\n", ops[i].name, ops[i].f(12, 5));
    printf("%d %d\n", (*ops[0].f)(1, 2), pick('-')(3, 4));
    int (*tbl[3])(int, int) = {add, sub, mul};
    int acc = 2;
    for (int i = 0; i < 3; i++) acc = tbl[i](acc, 3);
    printf("acc=%d ids=%d,%d,%d\n", acc, next_id(), next_id(), next_id());
    int v[] = {5, 3, 9, 1};
    qsort(v, 4, sizeof(int), cmp_desc);
    for (int i = 0; i < 4; i++) printf("%d ", v[i]);
    printf("| %d %d\n", fold(add, v, 4, 0), fold(mul, v, 4, 1));
    const char *words[] = {"pear", "apple", "fig", "banana"};
    qsort(words, 4, sizeof(words[0]), cmp_str);
    for (int i = 0; i < 4; i++) printf("%s ", words[i]);
    printf("\n");
    return 0;
}

