enum Kind { K_INT, K_DBL, K_STR };

struct Value {
    enum Kind kind;
    union {
        int i;
        double d;
        char s[8];
    } u;
};

void show(const struct Value *v) {
    switch (v->kind) {
    case K_INT: printf("int %d\n", v->u.i); break;
    case K_DBL: printf("dbl %.3f\n", v->u.d); break;
    case K_STR: printf("str '%s'\n", v->u.s); break;
    }
}

int process(int n) {
    int *a = NULL, *b = NULL;
    int rc = -1;
    a = malloc(n * sizeof *a);
    if (a == NULL) goto done;
    b = calloc(n, sizeof *b);
    if (b == NULL) goto done;
    rc = 0;
    for (int i = 0; i < n; i++) {
        a[i] = i * 3;
        b[i] = a[i] + 1;
        rc += b[i];
    }
done:
    free(b);
    free(a);
    return rc;
}

int main(void) {
    struct Value vs[3];
    vs[0].kind = K_INT; vs[0].u.i = -7;
    vs[1].kind = K_DBL; vs[1].u.d = 2.5;
    vs[2].kind = K_STR; strcpy(vs[2].u.s, "hey");
    for (int i = 0; i < 3; i++) show(&vs[i]);
    printf("%d %d\n", process(4), process(1));
