#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

void insert_sorted(Node **head, int v) {
    Node **pp = head;
    while (*pp && (*pp)->val < v) pp = &(*pp)->next;
    Node *n = (Node *)malloc(sizeof(Node));
    n->val = v;
    n->next = *pp;
    *pp = n;
}

int remove_val(Node **head, int v) {
    for (Node **pp = head; *pp; pp = &(*pp)->next)
        if ((*pp)->val == v) {
            Node *d = *pp;
            *pp = d->next;
            free(d);
            return 1;
        }
    return 0;
}

void map(Node *h, int (*f)(int)) {
    for (; h; h = h->next) h->val = f(h->val);
}

int twice(int x) { return 2 * x; }

void print(const Node *h) {
    printf("[");
    for (; h != NULL; h = h->next) printf("%d%s", h->val, h->next ? ", " : "");
    printf("]\n");
}

int length(const Node *h) { return h ? 1 + length(h->next) : 0; }

int main(void) {
    Node *head = NULL;
    int data[] = {5, 1, 9, 3, 7, 3};
    for (int i = 0; i < (int)(sizeof data / sizeof data[0]); i++)
        insert_sorted(&head, data[i]);
    print(head);
    int r1 = remove_val(&head, 3);
    int r2 = remove_val(&head, 4);
    printf("%d %d\n", r1, r2);
    map(head, twice);
    print(head);
    printf("len=%d\n", length(head));
    while (head) {
        Node *t = head->next;
        free(head);
        head = t;
    }
    print(head);
    return 0;
}
